    $('actHour').innerHTML = cols(hours) + ((early || late) ? '<p class="note">Fuera de horario: ' + early + ' antes de las 7 h · ' + late + ' después de las 23 h</p>' : '');
    $('actHourBox').style.display = F.per === '1' ? 'none' : '';

    // Temas y planes
    var tm = {}, pl = {};
    list.forEach(function (c) { var t = temaDe(c); tm[t] = (tm[t] || 0) + 1; planesDe(c).forEach(function (p) { pl[p] = (pl[p] || 0) + 1; }); });
    var tmL = Object.keys(tm).map(function (k) { return [k, tm[k]]; }).sort(function (a, b) { return (a[0] === 'Otros temas') - (b[0] === 'Otros temas') || b[1] - a[1]; });
    var plL = Object.keys(pl).map(function (k) { return ['Plan ' + k, pl[k]]; }).sort(function (a, b) { return b[1] - a[1]; }).slice(0, 8);
    $('temas').innerHTML = bars(tmL, Math.max.apply(null, tmL.map(function (x) { return x[1]; }).concat([0])), 'blue');
    $('planes').innerHTML = bars(plL, Math.max.apply(null, plL.map(function (x) { return x[1]; }).concat([0])), 'blue2');

    // Satisfacción
