    $('coments').innerHTML = coms.length ? coms.map(function (c) {
      return '<li><div class="cm-h"><span class="pill ' + (c.c === 1 ? 'up' : 'dn') + '">' + (c.c === 1 ? 'Útil' : 'No útil') + '</span><b>' + esc(c.n) + '</b><span class="muted mono">' + fmt(c.t) + '</span></div>' +
        '<p class="cm-t">“' + esc(c.m) + '”</p><p class="cm-q muted">Consulta: ' + esc(c.p.slice(0, 160)) + (c.p.length > 160 ? '…' : '') + '</p></li>';
    }).join('') : '<li class="empty">Sin comentarios en el período</li>';

    // Detalle
    var q = norm(F.q);
    var det = q ? list.filter(function (c) { return c.txt.indexOf(q) >= 0 || norm(c.r).indexOf(q) >= 0 || norm(c.n).indexOf(q) >= 0; }) : list;
    $('detCnt').textContent = det.length + ' consulta' + (det.length === 1 ? '' : 's');
    $('det').innerHTML = det.length ? det.slice(0, shown).map(function (c) {
      var cal = c.c === 1 ? '<span class="pill up">Útil</span>' : (c.c === 0 ? '<span class="pill dn">No útil</span>' : '<span class="pill nc">Sin calificar</span>');
      return '<tr class="dr"><td class="mono">' + fmt(c.t) + '</td><td class="who">' + esc(c.n) + '<small>' + esc(c.a) + '</small></td>' +
        '<td><div class="clamp">' + esc(c.p) + '</div></td><td><div class="clamp resp">' + esc(c.r) + '</div></td><td>' + cal + (c.m ? '<div class="cm-mini">“' + esc(c.m) + '”</div>' : '') + '</td></tr>';
    }).join('') : '<tr><td colspan="5" class="empty">No hay consultas para este filtro</td></tr>';
    $('more').style.display = det.length > shown ? '' : 'none';
    $('more').textContent = 'Ver más (' + Math.min(50, det.length - shown) + ' de ' + (det.length - shown) + ' restantes)';

    var vn = F.vend === 'all' ? '' : ' · ' + (people[F.vend] ? people[F.vend].n : (users[F.vend] ? users[F.vend].n : ''));
    $('scope').textContent = 'Mostrando: ' + perTxt + ' · ' + (F.area === 'all' ? 'todas las áreas' : F.area) + vn;
  }
  function kpi(v, l, s, cls) { return '<div class="kpi ' + cls + '"><span class="num">' + v + '</span><span class="lbl">' + l + '</span><span class="sub">' + esc(s) + '</span></div>'; }

  function fillVend() {
    var opts = {};
    habilitados.forEach(function (u) { if (inArea(u.a || 'Sin área')) opts[u.id] = u.n || 'Sin nombre'; });
    D.c.forEach(function (c) { if (inArea(c.a) && !opts[c.s]) opts[c.s] = c.n; });
    if (F.vend !== 'all' && !opts[F.vend]) F.vend = 'all';
    var ids = Object.keys(opts).sort(function (a, b) { return opts[a].localeCompare(opts[b]); });
    $('vendSel').innerHTML = '<option value="all">Todos los vendedores</option>' + ids.map(function (id) { return '<option value="' + esc(id) + '">' + esc(opts[id]) + '</option>'; }).join('');
  }

  // ---------- Controles ----------
  var areas = {};
  D.u.forEach(function (u) { areas[u.a || 'Sin área'] = 1; });
  D.c.forEach(function (c) { areas[c.a] = 1; });
  $('areaSel').innerHTML = '<option value="all">Todas las áreas</option>' + Object.keys(areas).sort().map(function (a) { return '<option value="' + esc(a) + '">' + esc(a) + '</option>'; }).join('');
  if (F.area !== 'all' && !areas[F.area]) F.area = 'all';
  $('q').value = F.q;

  document.addEventListener('click', function (ev) {
    var t = ev.target;
    var b = t.closest ? t.closest('[data-per]') : null;
    if (b) { F.per = b.getAttribute('data-per'); shown = 50; render(); return; }
    var r = t.closest ? t.closest('tr.rk') : null;
    if (r) { var v = r.getAttribute('data-v'); F.vend = F.vend === v ? 'all' : v; shown = 50; render(); $('detalle').scrollIntoView({ behavior: 'smooth' }); return; }
    var d = t.closest ? t.closest('tr.dr') : null;
    if (d) { d.classList.toggle('open'); return; }
    if (t.id === 'more') { shown += 50; render(); return; }
    if (t.id === 'clear') { F = { per: '7', area: 'all', vend: 'all', q: '' }; $('q').value = ''; shown = 50; render(); }
  });
  $('areaSel').addEventListener('change', function () { F.area = this.value; F.vend = 'all'; shown = 50; render(); });
  $('vendSel').addEventListener('change', function () { F.vend = this.value; shown = 50; render(); });
  var qt;
  $('q').addEventListener('input', function () { var v = this.value; clearTimeout(qt); qt = setTimeout(function () { F.q = v; shown = 50; render(); }, 250); });

  function clock() { $('clk').textContent = dtfClock.format(new Date()); }
  clock(); setInterval(clock, 30000);
  setInterval(function () { location.reload(); }, REFRESCO_MIN * 60000);
  render();
})();
